#!/usr/bin/env python3
from pathlib import Path

main_path = Path('3gx/sources/main.c')
trace_path = Path('reader_core/src/crystal/trace.rs')

m = main_path.read_text()
t = trace_path.read_text()


def rep(src: str, old: str, new: str, label: str) -> str:
    n = src.count(old)
    if n != 1:
        raise SystemExit(f'v786 {label}: expected 1 match, got {n}')
    return src.replace(old, new, 1)

# -------------------------------------------------------------------------
# v7.8.6: retire the failed host-wall-clock START-phase actuator from the
# current live Exact2 path. Instead, after B is released and BEFORE the probe
# / FFA4 pass is armed, allow N genuinely neutral VC frames to execute while
# every gameplay key is physically clear. This advances emulated DIV/RNG by
# normal game execution; it never writes RNG, DIV, DV, rJOYP, or any key value.
#
# Default N=3 because the historical v6.1c 3F trial landed at J=-149, inside
# the newly identified local shiny-capable band. X/Y at ROOT READY select
# 1..3 for fallback trials. 0F is deliberately omitted: current M14 already
# has ten authoritative 0F transports and all were globally shiny-impossible.
# -------------------------------------------------------------------------
needle = '''static u64 suicune_start_phase_actual_tick = 0;\n'''
insert = '''static u64 suicune_start_phase_actual_tick = 0;\n\n// v7.8.6 Neutral-Frame Phase Probe. These are game frames, not host waits.\nstatic u32 suicune_neutral_probe_frames = 3;\nstatic u32 suicune_neutral_probe_remaining = 0;\nstatic u32 suicune_neutral_probe_executed = 0;\nstatic bool suicune_neutral_probe_pending = false;\n'''
m = rep(m, needle, insert, 'add neutral probe state')

old_stage2 = '''        // v7.3.3 stage 2: after B-only ARM, wait frozen until B is fully\n        // released and physical UP is held. Then hand off to the unchanged\n        // Exact-2F scheduler. UP is intentionally excluded from its modifier\n        // release gate, so the two VC frames contain UP and no B.\n        // v7.6.7 stage 2: after B release, only physical UP may remain.\n        // If HID masking could not be armed, stay frozen (fail closed).\n        // Otherwise resume the VC continuously; rJOYP reads are masked in\n        // Rust for 16 input frames, passed for 2, then masked again.\n        if (suicune_wait_up_after_b)\n        {\n            const u32 stage2_block = KEY_A | KEY_B | KEY_X | KEY_Y |\n                KEY_DDOWN | KEY_DLEFT | KEY_DRIGHT | KEY_L | KEY_R |\n                KEY_START | KEY_SELECT;\n            if ((held & stage2_block) != 0)\n            {\n                svcSleepThread(1000000);\n                continue;\n            }\n            if (held & KEY_DUP)\n            {\n                if (!suicune_live_pass_ready)\n                {\n                    svcSleepThread(1000000);\n                    continue;\n                }\n\n                // v7.8.5 SHINY PHASE PROBE. The real-UP Exact2 mechanism is\n                // unchanged. While still frozen, align the *release into* the\n                // live 16-mask + 2-pass path to one selected absolute host\n                // display-cycle slot. No RNG/DIV/GB input value is written.\n                // UP may be held during this wait because the VC is still\n                // paused; once released, the existing live mask remains the\n                // authority until the two FFA4 polls are passed.\n                u64 now = svcGetSystemTick();\n                u32 wanted_start = suicune_start_phase_slot & 15U;\n                u64 cycle = now / SUICUNE_PHASE_PERIOD_TICKS + 1ULL;\n                while (((u32)cycle & 15U) != wanted_start) cycle++;\n                u64 target = cycle * SUICUNE_PHASE_PERIOD_TICKS;\n                if (target <= now + 4096ULL)\n                {\n                    cycle += 16ULL;\n                    target = cycle * SUICUNE_PHASE_PERIOD_TICKS;\n                }\n                suicune_start_phase_lock_active = true;\n                suicune_start_phase_anchor_tick = now;\n                suicune_start_phase_target_tick = target;\n                while (svcGetSystemTick() < target) { }\n                suicune_start_phase_actual_tick = svcGetSystemTick();\n\n                // v7.6.7d: no paused write-test. The only meaningful test is\n                // the hook-timed clear immediately before Crystal reads rJOYP.\n                suicune_wait_up_after_b = false;\n                fixed_frames_remaining = 0;\n                fixed_run_pending = false;\n                fixed_armed = false;\n                suicune_auto_resume_pending = false;\n                suicune_phase_lock_active = false;\n                is_paused = false;\n                break;\n            }\n            svcSleepThread(1000000);\n            continue;\n        }\n'''
new_stage2 = '''        // v7.8.6 NEUTRAL FRAME PHASE PROBE.\n        // B is accepted while frozen. After B and every other gameplay key\n        // are physically clear, pass exactly N *real VC game frames* with no\n        // input. is_paused remains true, so each `break` releases only one\n        // frame and the next bottom hook freezes again.\n        //\n        // Only after all N frames are complete do we capture the authoritative\n        // post-delay Target and arm the existing live FFA4 mask/pass primitive.\n        // Thus the two UP polls and the v7.6.7j M14 post-Exact2 resume path are\n        // unchanged. No host START-phase wait is used here.\n        if (suicune_wait_up_after_b)\n        {\n            if (suicune_neutral_probe_pending)\n            {\n                const u32 neutral_block = KEY_A | KEY_B | KEY_X | KEY_Y |\n                    KEY_DUP | KEY_DDOWN | KEY_DLEFT | KEY_DRIGHT |\n                    KEY_L | KEY_R | KEY_START | KEY_SELECT;\n                if ((held & neutral_block) != 0)\n                {\n                    // Fail closed if UP is pressed early: do not consume any\n                    // neutral frame until the user releases every gameplay key.\n                    svcSleepThread(1000000);\n                    continue;\n                }\n\n                if (suicune_neutral_probe_remaining > 0)\n                {\n                    suicune_neutral_probe_remaining--;\n                    suicune_neutral_probe_executed++;\n                    break; // exactly one input-neutral VC frame\n                }\n\n                // We are frozen immediately after the Nth neutral frame. Arm\n                // the probe NOW so ProbeTarget/PREFP describe the actual root\n                // from which the physical-UP Exact2 path starts.\n                suicune_neutral_probe_pending = false;\n                arm_suicune_probe();\n                suicune_live_pass_ready = arm_suicune_live_pass() != 0;\n                suicune_observe_reset();\n                suicune_early_lab_reset();\n                suicune_obs_arm_tick = svcGetSystemTick();\n                fixed_a_frames = 2;\n                fixed_frames_remaining = 0;\n                fixed_armed = true;\n                fixed_run_pending = false;\n                suicune_auto_resume_pending = false;\n                suicune_phase_lock_active = false;\n                suicune_start_phase_lock_active = false;\n                continue;\n            }\n\n            // Neutral delay is complete. From here this is the proven v7.6.7\n            // physical-UP -> FFA4 Exact2 entry gate. B/Y/X/etc. are forbidden;\n            // only physical UP may remain.\n            const u32 stage2_block = KEY_A | KEY_B | KEY_X | KEY_Y |\n                KEY_DDOWN | KEY_DLEFT | KEY_DRIGHT | KEY_L | KEY_R |\n                KEY_START | KEY_SELECT;\n            if ((held & stage2_block) != 0)\n            {\n                svcSleepThread(1000000);\n                continue;\n            }\n            if (held & KEY_DUP)\n            {\n                if (!suicune_live_pass_ready)\n                {\n                    svcSleepThread(1000000);\n                    continue;\n                }\n\n                // v7.6.7d unchanged: the meaningful verification is the\n                // hook-timed FFA4 clear/pass immediately before Crystal reads\n                // rJOYP. No START host-phase wait is performed.\n                suicune_wait_up_after_b = false;\n                fixed_frames_remaining = 0;\n                fixed_run_pending = false;\n                fixed_armed = false;\n                suicune_auto_resume_pending = false;\n                suicune_phase_lock_active = false;\n                is_paused = false;\n                break;\n            }\n            svcSleepThread(1000000);\n            continue;\n        }\n'''
m = rep(m, old_stage2, new_stage2, 'replace live stage2 with neutral frames')

old_selector = '''        // v7.8.5 start-slot selector. Exact2 release/resume is deliberately\n        // fixed at M14 by v7.6.7j, so X/Y now select only the host cycle at\n        // which the live masked path begins. This isolates the upstream\n        // transport-phase lever under test.\n        if (suicune_root_lock_ready && !fixed_run_pending && !suicune_auto_resume_pending)\n        {\n            if (just_pressed & KEY_X)\n            {\n                suicune_start_phase_slot = (suicune_start_phase_slot + 1U) & 15U;\n                continue;\n            }\n            if (just_pressed & KEY_Y)\n            {\n                suicune_start_phase_slot = (suicune_start_phase_slot + 15U) & 15U;\n                continue;\n            }\n        }\n'''
new_selector = '''        // v7.8.6 neutral-frame selector. Default 3F. X/Y change only the\n        // number of natural, input-neutral VC frames inserted before the probe\n        // is armed; host wall-clock phase is not a control variable.\n        if (suicune_root_lock_ready && !fixed_run_pending && !suicune_auto_resume_pending)\n        {\n            if (just_pressed & KEY_X)\n            {\n                suicune_neutral_probe_frames++;\n                if (suicune_neutral_probe_frames > 3U) suicune_neutral_probe_frames = 1U;\n                suicune_start_phase_slot = suicune_neutral_probe_frames; // telemetry only\n                continue;\n            }\n            if (just_pressed & KEY_Y)\n            {\n                if (suicune_neutral_probe_frames <= 1U) suicune_neutral_probe_frames = 3U;\n                else suicune_neutral_probe_frames--;\n                suicune_start_phase_slot = suicune_neutral_probe_frames; // telemetry only\n                continue;\n            }\n        }\n'''
m = rep(m, old_selector, new_selector, 'replace start slot selector')

old_arm = '''        if ((held & KEY_B) && !(held & KEY_Y)\n            && suicune_root_lock_ready\n            && !suicune_wait_up_after_b\n            && !fixed_run_pending && !suicune_auto_resume_pending)\n        {\n            suicune_root_lock_ready = false;\n            suicune_root_lock_active = false;\n            arm_suicune_probe();\n            suicune_live_pass_ready = arm_suicune_live_pass() != 0;\n            suicune_observe_reset();\n            suicune_early_lab_reset();\n            suicune_obs_arm_tick = svcGetSystemTick();\n            fixed_a_frames = 2;\n            fixed_frames_remaining = 0;\n            fixed_armed = true;\n            fixed_run_pending = false;\n            suicune_auto_resume_pending = false;\n            suicune_wait_up_after_b = true;\n            suicune_phase_lock_active = true;\n            suicune_phase_anchor_tick = 0;\n            suicune_phase_target_tick = 0;\n            suicune_phase_actual_tick = 0;\n            // v7.8.5: preserve the user-selected live-start slot across B ARM.\n            suicune_start_phase_lock_active = true;\n            suicune_start_phase_anchor_tick = 0;\n            suicune_start_phase_target_tick = 0;\n            suicune_start_phase_actual_tick = 0;\n            continue;\n        }\n'''
new_arm = '''        if ((held & KEY_B) && !(held & KEY_Y)\n            && suicune_root_lock_ready\n            && !suicune_wait_up_after_b\n            && !fixed_run_pending && !suicune_auto_resume_pending)\n        {\n            // Consume B while frozen, but deliberately postpone ProbeTarget and\n            // FFA4-mask arming until after the selected neutral VC frames.\n            suicune_root_lock_ready = false;\n            suicune_root_lock_active = false;\n            suicune_live_pass_ready = false;\n            suicune_neutral_probe_remaining = suicune_neutral_probe_frames;\n            suicune_neutral_probe_executed = 0;\n            suicune_neutral_probe_pending = true;\n            suicune_start_phase_slot = suicune_neutral_probe_frames; // existing telemetry channel\n            fixed_a_frames = 2;\n            fixed_frames_remaining = 0;\n            fixed_armed = false;\n            fixed_run_pending = false;\n            suicune_auto_resume_pending = false;\n            suicune_wait_up_after_b = true;\n            suicune_phase_lock_active = false;\n            suicune_start_phase_lock_active = false;\n            suicune_start_phase_anchor_tick = 0;\n            suicune_start_phase_target_tick = 0;\n            suicune_start_phase_actual_tick = 0;\n            continue;\n        }\n'''
m = rep(m, old_arm, new_arm, 'delay probe arm until neutral frames complete')

old_scan = '''                suicune_phase_slot = 0; // v7.6.6 diagnostic default: absolute Resume M0\n                search_suicune_practical_targets();'''
new_scan = '''                suicune_phase_slot = 0; // post-Exact2 is still hard-fixed M14 by v7.6.7j\n                suicune_neutral_probe_frames = 3;\n                suicune_neutral_probe_remaining = 0;\n                suicune_neutral_probe_executed = 0;\n                suicune_neutral_probe_pending = false;\n                suicune_start_phase_slot = suicune_neutral_probe_frames; // telemetry only\n                search_suicune_practical_targets();'''
m = rep(m, old_scan, new_scan, 'reset neutral selector at live scan')

# Rust UI + CSV. practical_live_found_* is the locked A/r10/B76 root before
# neutral frames. probe_target is captured after the Nth neutral frame.
t = t.replace('S785 PHASE SCAN A/r10 B76', 'S786 NEUTRAL SCAN A/r10 B76')

old_ui = '''        } else if self.practical_live_found_lane == 252 && !self.probe_session {\n            let sp = pnp::start_phase_metrics();\n            pnp::println!("S785 PHASE ROOT READY");\n            pnp::println!("A/r10 B76 S{:04X} D{:04X}",self.practical_live_found_state,self.practical_live_found_div);\n            pnp::println!("START M{:02} X+1 Y-1",sp.slot & 15);\n            pnp::println!("RESUME M14 FIXED");\n            pnp::println!("B ARM -> RELEASE -> HOLD UP");\n'''
new_ui = '''        } else if self.practical_live_found_lane == 252 && !self.probe_session {\n            let sp = pnp::start_phase_metrics();\n            pnp::println!("S786 NEUTRAL ROOT READY");\n            pnp::println!("A/r10 B76 S{:04X} D{:04X}",self.practical_live_found_state,self.practical_live_found_div);\n            pnp::println!("NEUTRAL {}F X+1 Y-1",sp.slot);\n            pnp::println!("RESUME M14 FIXED");\n            pnp::println!("B -> RELEASE; WAIT -> UP");\n'''
t = rep(t, old_ui, new_ui, 'replace root-ready UI')

old_csv = '''        if self.practical_live_found_lane == 252 {\n            let sp = pnp::start_phase_metrics();\n            let rp = pnp::resume_phase_metrics();\n            let start_mod = if sp.period != 0 { ((sp.actual / sp.period) & 15) as u32 } else { 255 };\n            let resume_mod = if rp.period != 0 { ((rp.actual / rp.period) & 15) as u32 } else { 255 };\n            let start_err = sp.actual as i128 - sp.target as i128;\n            let raw = self.probe_result.map(|x| x.raw_dv).unwrap_or(0);\n            let route = self.probe_result.map(|x| x.route).unwrap_or(0);\n            line.clear();\n            let _ = write!(line,\n                "\\nphase_probe785,version,root_advance,root_state,root_div,bucket,start_slot,start_actual_mod16,start_error_ticks,resume_slot,resume_actual_mod16,j_a,j_s,post_proto,post_rot,route,raw_dv\\nPHASEPROBE,V785,{},{:04X},{:04X},{},{},{},{},{},{},{},{},{},{},{},{:04X}\\n",\n                self.practical_live_found_advance,self.practical_live_found_state,self.practical_live_found_div,\n                self.bucket_current,sp.slot&15,start_mod,start_err,rp.slot&15,resume_mod,\n                self.early_j_a,self.early_j_s,\n                if self.practical_post_proto==0{'?'}else{self.practical_post_proto as char},self.practical_post_rot,\n                route,raw);\n            pnp::trace_file_write(line.as_bytes());\n        }\n'''
new_csv = '''        if self.practical_live_found_lane == 252 {\n            let sp = pnp::start_phase_metrics();\n            let rp = pnp::resume_phase_metrics();\n            let resume_mod = if rp.period != 0 { ((rp.actual / rp.period) & 15) as u32 } else { 255 };\n            let raw = self.probe_result.map(|x| x.raw_dv).unwrap_or(0);\n            let route = self.probe_result.map(|x| x.route).unwrap_or(0);\n            let neutral_delta = self.probe_target.advance.wrapping_sub(self.practical_live_found_advance);\n            line.clear();\n            let _ = write!(line,\n                "\\nneutral_probe786,version,locked_root_advance,armed_target_advance,advance_delta,locked_state,armed_state,locked_div,armed_div,bucket,neutral_requested,resume_slot,resume_actual_mod16,j_a,j_s,post_proto,post_rot,route,raw_dv\\nNEUTRALPROBE,V786,{},{},{},{:04X},{:04X},{:04X},{:04X},{},{},{},{},{},{},{},{},{:04X}\\n",\n                self.practical_live_found_advance,self.probe_target.advance,neutral_delta,\n                self.practical_live_found_state,self.probe_target.state,\n                self.practical_live_found_div,self.probe_target.div,\n                self.bucket_current,sp.slot,rp.slot&15,resume_mod,\n                self.early_j_a,self.early_j_s,\n                if self.practical_post_proto==0{'?'}else{self.practical_post_proto as char},self.practical_post_rot,\n                route,raw);\n            pnp::trace_file_write(line.as_bytes());\n        }\n'''
t = rep(t, old_csv, new_csv, 'replace phase probe CSV')

t = t.replace('v7.8.5 SHINY-CAPABLE PHASE PROBE.', 'v7.8.6 NEUTRAL-FRAME SHINY-CAPABLE PROBE.')
t = t.replace('transport experiment, hold PRE class and bucket constant and vary\n        // only the host live-start slot.', 'transport experiment, hold the comparison root constant up to ROOT READY,\n        // then vary only the number of real input-neutral VC frames before arm.')

main_path.write_text(m)
trace_path.write_text(t)
print('Applied Suicune v7.8.6 Neutral-Frame Phase Probe')
